// Plan: specs/burger-menu.md. Generated by the Playwright Test Agents, then
// consolidated (ADR 0006). Quirk numbers refer to the plan's "Observed quirks".
// No Cypress twin yet (docs/test-strategy.md, "Tests with no Cypress twin").
import { test, expect } from '../../src/fixtures/test';
import { notLoggedInError } from '../../src/data/errors';

test.describe('Burger menu', () => {
  test.describe('open and close', () => {
    // Manual check replaced: opening the burger menu, reading the four item labels, and closing it with the X.
    test('opens with the expected items and closes with the X', async ({ loggedIn, menu }) => {
      for (const item of menu.items) await expect(item).toBeHidden();

      await menu.open();
      await expect(menu.allItemsLink).toHaveText('All Items');
      await expect(menu.aboutLink).toHaveText('About');
      await expect(menu.logoutLink).toHaveText('Logout');
      await expect(menu.resetLink).toHaveText('Reset App State');
      await expect(menu.closeButton).toBeVisible();

      await menu.close();
      for (const item of menu.items) await expect(item).toBeHidden();
      await loggedIn.expectLoaded();
      await expect(loggedIn.items).toHaveCount(6);
      await expect(loggedIn.cartBadge).toHaveCount(0);
    });

    // Manual check replaced: pressing Escape on the open menu to see whether it dismisses.
    // Clicking outside is not asserted (quirk 3: a coordinate click breaks on ui-mobile).
    test('Escape closes the menu', async ({ page, loggedIn, menu }) => {
      await menu.open();
      const urlBefore = page.url();

      // Escape closing the menu is observed third-party behaviour (quirk 3).
      await page.keyboard.press('Escape');
      for (const item of menu.items) await expect(item).toBeHidden();
      await expect(page).toHaveURL(urlBefore);
      await loggedIn.expectLoaded();
    });
  });

  test.describe('All Items and About', () => {
    // Manual check replaced: from the cart, a product page and checkout, using the burger menu
    // to get back to the product list and checking the cart is untouched.
    test('All Items returns to inventory from cart, product detail and checkout', async ({
      page,
      loggedIn,
      cartPage,
      productDetailPage,
      menu,
    }) => {
      const expectBackOnInventory = async () => {
        await loggedIn.expectLoaded();
        await expect(loggedIn.items).toHaveCount(6);
        await expect(loggedIn.cartBadge).toHaveText('1');
      };

      await loggedIn.addToCart('Sauce Labs Backpack');

      await test.step('from the cart', async () => {
        await loggedIn.openCart();
        await cartPage.expectLoaded();
        await menu.allItems();
        await expectBackOnInventory();
        await expect(loggedIn.removeButton('sauce-labs-backpack')).toBeVisible();
        // Quirk 5: navigating to a new page renders the menu closed.
        await expect(menu.allItemsLink).toBeHidden();
      });

      await test.step('from a product detail page', async () => {
        await productDetailPage.goto(4);
        await menu.allItems();
        await expectBackOnInventory();
      });

      await test.step('from checkout step one', async () => {
        await loggedIn.openCart();
        await cartPage.checkout();
        await expect(page).toHaveURL(/checkout-step-one\.html/);
        await menu.allItems();
        await expectBackOnInventory();
      });
    });

    // Manual check replaced: opening the menu and checking where About points.
    test('About links to saucelabs.com in the same tab', async ({ loggedIn, menu }) => {
      void loggedIn;
      await menu.open();
      // Quirk 6: About leaves the app, in the same tab, to a third-party site. It is not clicked,
      // so CI never depends on saucelabs.com loading. The href plus no target covers the manual check.
      await expect(menu.aboutLink).toHaveAttribute('href', 'https://saucelabs.com/');
      await expect(menu.aboutLink).not.toHaveAttribute('target');
    });
  });

  test.describe('Logout', () => {
    // Manual check replaced: logging out through the menu, then pressing browser back and typing
    // /inventory.html and /cart.html to confirm they are blocked.
    test('logout returns to login and blocks protected pages @smoke', async ({ page, loggedIn, loginPage, menu }) => {
      void loggedIn;
      await menu.logout();
      await expect(page).toHaveURL(/\/$/);
      await expect(loginPage.loginButton).toBeVisible();
      await expect(loginPage.username).toHaveValue('');
      await expect(loginPage.password).toHaveValue('');
      // Quirk 7: no error banner right after Logout.
      await expect(loginPage.error).toHaveCount(0);

      // The banner wording is third-party behaviour (quirk 7): it names the page requested.
      await page.goBack();
      await expect(page).toHaveURL(/\/$/);
      await expect(loginPage.error).toContainText(notLoggedInError('/inventory.html'));

      await page.goto('/inventory.html');
      await expect(page).toHaveURL(/\/$/);
      await expect(loginPage.error).toContainText(notLoggedInError('/inventory.html'));

      await page.goto('/cart.html');
      await expect(page).toHaveURL(/\/$/);
      await expect(loginPage.error).toContainText(notLoggedInError('/cart.html'));
    });
  });

  test.describe('Reset App State', () => {
    // Manual check replaced: filling the cart, choosing Reset App State, checking the badge and button
    // labels without refreshing, then refreshing and checking the cart page and buttons.
    test('Reset App State leaves the page stale until reload, then the cart is empty', async ({
      page,
      loggedIn,
      cartPage,
      menu,
    }) => {
      await test.step('on the inventory page', async () => {
        await loggedIn.addToCart('Sauce Labs Backpack');
        await loggedIn.addToCart('Sauce Labs Bike Light');
        await expect(loggedIn.cartBadge).toHaveText('2');

        await menu.resetAppState();
        await expect(loggedIn.cartBadge).toHaveCount(0);
        await loggedIn.expectLoaded();
        // Quirk 5: Reset App State does not close the menu.
        await expect(menu.resetLink).toBeVisible();
        // Quirk 2: Reset App State does not refresh the page, so the cards are stale.
        await expect(loggedIn.removeButton('sauce-labs-backpack')).toBeVisible();
        await expect(loggedIn.removeButton('sauce-labs-bike-light')).toBeVisible();
        await expect(loggedIn.addToCartButton('sauce-labs-backpack')).toHaveCount(0);

        await page.reload();
        await expect(loggedIn.addToCartButton('sauce-labs-backpack')).toBeVisible();
        await expect(loggedIn.addToCartButton('sauce-labs-bike-light')).toBeVisible();
        await expect(loggedIn.removeButton('sauce-labs-backpack')).toHaveCount(0);
        await expect(loggedIn.removeButton('sauce-labs-bike-light')).toHaveCount(0);
        await expect(loggedIn.cartBadge).toHaveCount(0);

        await loggedIn.openCart();
        await cartPage.expectLoaded();
        await expect(cartPage.items).toHaveCount(0);
      });

      await test.step('on the cart page', async () => {
        await page.goto('/inventory.html');
        await loggedIn.expectLoaded();
        await loggedIn.addToCart('Sauce Labs Backpack');
        await loggedIn.openCart();
        await cartPage.expectLoaded();
        await expect(cartPage.items).toHaveCount(1);

        await menu.resetAppState();
        await expect(loggedIn.cartBadge).toHaveCount(0);
        // Quirk 2: the cart page still lists the old line until reloaded.
        await expect(cartPage.itemNames).toHaveText(['Sauce Labs Backpack']);
        await page.reload();
        await expect(cartPage.items).toHaveCount(0);
      });
    });
  });
});
